-- PostgreSQL schema from the final Spring/Liquibase release (seven change sets).
CREATE SCHEMA expensetracker;
CREATE TABLE expensetracker.expenses (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  expense_date TIMESTAMPTZ, description TEXT, location TEXT, category TEXT,
  amount NUMERIC(19,4), currency TEXT, method TEXT, type TEXT, comment TEXT,
  converted_amount NUMERIC(19,4), base_currency TEXT
);
CREATE TABLE expensetracker.categories (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL UNIQUE, emoji TEXT, description TEXT
);
CREATE TABLE expensetracker.merchant_categories (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  merchant TEXT NOT NULL UNIQUE, category TEXT NOT NULL
);
CREATE TABLE expensetracker.settings (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  closing_day INTEGER NOT NULL, monthly_budget NUMERIC(11,2) DEFAULT 0 NOT NULL
);
CREATE TABLE expensetracker.databasechangelog (
  id VARCHAR(255) NOT NULL, author VARCHAR(255) NOT NULL,
  filename VARCHAR(255) NOT NULL, dateexecuted TIMESTAMP NOT NULL,
  orderexecuted INTEGER NOT NULL, exectype VARCHAR(10) NOT NULL,
  md5sum VARCHAR(35), description VARCHAR(255), comments VARCHAR(255),
  tag VARCHAR(255), liquibase VARCHAR(20), contexts VARCHAR(255),
  labels VARCHAR(255), deployment_id VARCHAR(10)
);
INSERT INTO expensetracker.databasechangelog (id, author, filename, dateexecuted, orderexecuted, exectype)
SELECT id, 'mucsi96', 'db/changelog/db.changelog-master.yaml', '2026-11-01', ordinality, 'EXECUTED'
FROM unnest(ARRAY['1-create-expenses-table', '2-add-converted-amount', '3-create-categories-table',
  '4-add-category-emoji-and-description', '5-create-merchant-categories-table', '6-create-settings-table',
  '7-add-monthly-budget']) WITH ORDINALITY AS changes(id, ordinality);
CREATE TABLE expensetracker.databasechangeloglock (
  id INTEGER PRIMARY KEY, locked BOOLEAN NOT NULL, lockgranted TIMESTAMP, lockedby VARCHAR(255)
);
INSERT INTO expensetracker.databasechangeloglock VALUES (1, false, NULL, NULL);
