SELECT setval(pg_get_serial_sequence('expensetracker.categories', 'id'), 500);
SELECT setval(pg_get_serial_sequence('expensetracker.merchant_categories', 'id'), 600);
SELECT setval(pg_get_serial_sequence('expensetracker.settings', 'id'), 700);
